26	import java.util.concurrent.ConcurrentHashMap;
27	import java.util.concurrent.atomic.AtomicLong;
28	import java.util.stream.Collectors;
29	
30	import org.slf4j.Logger;
31	import org.slf4j.LoggerFactory;
32	import org.springframework.http.HttpHeaders;
33	import org.springframework.http.HttpStatus;
34	import org.springframework.http.ResponseEntity;
35	import org.springframework.samples.petclinic.mapper.OwnerMapper;
36	import org.springframework.samples.petclinic.mapper.PetMapper;
37	import org.springframework.samples.petclinic.mapper.VisitMapper;
38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.advice.CityCapacityExceededException;
42	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
44	import org.springframework.samples.petclinic.rest.advice.InvalidFieldsException;
45	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
46	import org.springframework.samples.petclinic.rest.api.OwnersApi;
47	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
48	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.PetDto;
50	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitDto;
52	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
53	import org.springframework.samples.petclinic.service.ClinicService;
54	import org.springframework.security.access.prepost.PreAuthorize;
55	import org.springframework.web.bind.annotation.CrossOrigin;
56	import org.springframework.web.bind.annotation.RequestMapping;
57	import org.springframework.web.bind.annotation.RestController;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.servlet.http.HttpServletRequest;
61	import jakarta.transaction.Transactional;
62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
75	
76	    private final ClinicService clinicService;
77	
78	    private final OwnerMapper ownerMapper;
79	
80	    private final PetMapper petMapper;
81	
82	    private final VisitMapper visitMapper;
83	
84	    private final HttpServletRequest request;
85	
86	    /**
87	     * HTTP header carrying the client-supplied idempotency key for the create endpoint. When a
88	     * create repeats with a key already seen, the originally created owner is returned instead of
89	     * creating a duplicate.
90	     */
91	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
92	
93	    /**
94	     * Remembers, per seen {@code Idempotency-Key}, the id of the owner that key's create produced,
95	     * so a repeat create with the same key can return the originally created owner rather than
96	     * persisting a duplicate. Shared across requests, hence concurrency-safe.
97	     */
98	    private static final Map<String, Integer> IDEMPOTENT_CREATES = new ConcurrentHashMap<>();
99	
100	    /**
101	     * Source of the {@code seq} carried by each structured {@code OWNER_CREATED} audit event: a
102	     * monotonically increasing integer stamped once per successful create, in creation order.
103	     * Shared across requests, hence concurrency-safe.
104	     */
105	    private static final AtomicLong OWNER_CREATED_SEQ = new AtomicLong(0);
106	
107	    public OwnerRestControllerV1(ClinicService clinicService,
108	                                 OwnerMapper ownerMapper,
109	                                 PetMapper petMapper,
110	                                 VisitMapper visitMapper,
111	                                 HttpServletRequest request) {
112	        this.clinicService = clinicService;
113	        this.ownerMapper = ownerMapper;
114	        this.petMapper = petMapper;
115	        this.visitMapper = visitMapper;
116	        this.request = request;
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
122	        Collection<Owner> owners;
123	        if (lastName != null) {
124	            owners = this.clinicService.findOwnerByLastName(lastName);
125	        } else {
126	            owners = this.clinicService.findAllOwners();
127	        }
128	        if (owners.isEmpty()) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
137	        Owner owner = this.clinicService.findOwnerById(ownerId);
138	        if (owner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        return okOwnerResponse(owner);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
147	        String idempotencyKey = idempotencyKey();
148	        if (idempotencyKey != null) {
149	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
150	            if (replay != null) {
151	                return replay;
152	            }
153	        }
154	        Owner owner = createOwner(ownerFieldsDto);
155	        if (idempotencyKey != null) {
156	            IDEMPOTENT_CREATES.put(idempotencyKey, owner.getId());
157	        }
158	        return createdOwnerResponse(owner);
159	    }
160	
161	    /**
162	     * Reads the request's {@code Idempotency-Key} header, returning the trimmed key or {@code null}
163	     * when the header is absent or blank. A blank key carries no intent to deduplicate, so the
164	     * create proceeds normally.
165	     *
166	     * @return the non-blank idempotency key, or {@code null} when none was supplied
167	     */
168	    private String idempotencyKey() {
169	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
170	        if (key == null || key.isBlank()) {
171	            return null;
172	        }
173	        return key.trim();
174	    }
175	
176	    /**
177	     * Replays the create originally produced by the given {@code Idempotency-Key}, if any: when the
178	     * key has already created an owner that still exists, that owner is rendered with {@code 200 OK}
179	     * (rather than creating a duplicate with {@code 201 Created}). When the key has not been seen, or
180	     * the owner it created no longer exists, {@code null} is returned so the caller creates the owner
181	     * normally.
182	     *
183	     * @param idempotencyKey the non-blank idempotency key supplied on the request
184	     * @return the {@code 200 OK} response carrying the originally created owner, or {@code null}
185	     */
186	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
187	        Integer existingId = IDEMPOTENT_CREATES.get(idempotencyKey);
188	        if (existingId == null) {
189	            return null;
190	        }
191	        Owner existing = this.clinicService.findOwnerById(existingId);
192	        if (existing == null) {
193	            return null;
194	        }
195	        return okOwnerResponse(existing);
196	    }
197	
198	    /**
199	     * Runs the full intake pipeline for a newly submitted owner and persists the result, returning
200	     * the saved {@link Owner}. The submitted fields are normalized and validated
201	     * ({@link #prepareNewOwner(OwnerFieldsDto, LocalDate)}) against the effective business-day
202	     * {@code registrationDate} ({@link #effectiveRegistrationDate(OwnerFieldsDto)}); the owner is
203	     * then mapped, stamped with that registration date and every derived value (member id,
204	     * namesake count, household), flagged as a possible duplicate where applicable, saved, and
205	     * finally stamped with its household member count. A rule that rejects the owner signals it by
206	     * throwing, which the exception advice renders as the matching 4xx response, so this method
207	     * returns only for an owner that was accepted and persisted. The create is audited once the
208	     * owner has its identity.
209	     *
210	     * <p>The returned owner carries its generated id and every stored field, ready to be rendered by
211	     * {@link #createdOwnerResponse(Owner)}.
212	     *
213	     * @param ownerFieldsDto the submitted owner fields, normalized in place
214	     * @return the persisted owner
215	     */
216	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
217	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto);
218	        prepareNewOwner(ownerFieldsDto, registrationDate);
219	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
220	        owner.setRegistrationDate(registrationDate);
221	        owner.setMemberId(memberIdFor(owner));
222	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
223	        assignHousehold(owner);
224	        applyPossibleDuplicate(owner, ownerFieldsDto);
225	        owner.setMembershipLevelCap(householdMembershipLevelCap(owner.getHouseholdId()));
226	        this.clinicService.saveOwner(owner);
227	        applyHouseholdMemberCount(owner);
228	        auditOwnerCreated(owner);
229	        emitOwnerCreatedEvent(owner);
230	        enqueueWelcomeNotification(owner);
231	        return owner;
232	    }
233	
234	    /**
235	     * Enqueues a welcome notification for a freshly persisted owner by emitting a line to the
236	     * dedicated {@code NOTIFY} logger carrying the owner's {@code id} and its unified
237	     * {@code memberId}. This runs only on a successful create — once the owner has its generated
238	     * identity and derived member id — so downstream consumers watching the {@code NOTIFY} logger
239	     * can react to new members structurally.
240	     *
241	     * @param owner the persisted owner, already carrying its generated id and derived member id
242	     */
243	    private void enqueueWelcomeNotification(Owner owner) {
244	        NOTIFY.info("Welcome notification queued: id={} memberId={}",
245	            owner.getId(), owner.getMemberId());
246	    }
247	
248	    /**
249	     * Writes the human-readable {@code Owner created} audit line for a freshly persisted owner,
250	     * carrying its {@code id}, its unified {@code memberId}, its stored {@code registrationDate} and
251	     * its derived {@code membershipLevel}. This is the free-form companion to the structured
252	     * {@code OWNER_CREATED} event (see {@link #emitOwnerCreatedEvent(Owner)}); isolating it here
253	     * keeps {@link #createOwner(OwnerFieldsDto)} a thin orchestration and gives the audit line one
254	     * place to grow.
255	     *
256	     * @param owner the persisted owner, already carrying its generated id and derived values
257	     */
258	    private void auditOwnerCreated(Owner owner) {
259	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
260	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
261	            owner.getMembershipLevel());
262	    }
263	
264	    /**
265	     * Emits the immutable, structured {@code OWNER_CREATED} audit event for a freshly persisted owner,
266	     * alongside the human-readable audit line. The event is the version-2 schema: a JSON object
267	     * carrying, in order, a {@code seq} (a monotonically increasing integer across creates, see
268	     * {@link #OWNER_CREATED_SEQ}), a {@code schemaVersion} of {@code 2}, the owner's {@code ownerId},
269	     * the owner's current primary identifier (see {@link #primaryIdentifier(Owner)}) under the
270	     * {@code memberId} key, the owner's derived {@code membershipLevel}, the owner's
271	     * {@code ownerSegment} recomputed from its version-2 identity (see
272	     * {@link #ownerSegment(Owner)}), and the {@code event} marker {@code 'OWNER_CREATED'}. Published
273	     * to the dedicated {@code AUDIT} logger so downstream consumers can react to owner creation
274	     * structurally rather than by parsing the free-form line.
275	     *
276	     * @param owner the persisted owner, already carrying its generated id and derived values
277	     */
278	    private void emitOwnerCreatedEvent(Owner owner) {
279	        long seq = OWNER_CREATED_SEQ.incrementAndGet();
280	        Map<String, String> event = new java.util.LinkedHashMap<>();
281	        event.put("seq", Long.toString(seq));
282	        event.put("schemaVersion", "2");
283	        event.put("ownerId", String.valueOf(owner.getId()));
284	        event.put("memberId", jsonString(primaryIdentifier(owner)));
285	        event.put("membershipLevel", String.valueOf(owner.getMembershipLevel()));
286	        event.put("ownerSegment", jsonString(ownerSegment(owner)));
287	        event.put("event", jsonString("OWNER_CREATED"));
288	        AUDIT.info("{}", jsonObject(event));
289	    }
290	
291	    /**
292	     * Recomputes the owner's segment for the version-2 {@code OWNER_CREATED} audit event, rendering
293	     * the owner's derived segment (for example {@code 'STANDARD_METRO'}, see
294	     * {@link OwnerMapper#ownerSegment(Owner)}) as its bare string. The segment is derived from the
295	     * owner's membership level and its plain, user-facing region, so it never carries the identity
296	     * version tag. Returns {@code null} when the owner has no derivable segment, which the event
297	     * renders as JSON {@code null}.
298	     *
299	     * @param owner the persisted owner, already carrying its generated id and derived values
300	     * @return the owner's segment as a bare string, or {@code null} when none is derivable
301	     */
302	    private String ownerSegment(Owner owner) {
303	        OwnerDto.OwnerSegmentEnum segment = ownerMapper.ownerSegment(owner);
304	        return segment == null ? null : segment.getValue();
305	    }
306	
307	    /**
308	     * Returns the owner's current primary identifier, the single identity the structured
309	     * {@code OWNER_CREATED} event carries: the owner's unified {@code memberId}. This is the one seam
310	     * that decides which field is primary, so the event carries the member id under its
311	     * {@code memberId} key.
312	     *
313	     * @param owner the persisted owner whose primary identifier the event should carry
314	     * @return the owner's current primary identifier
315	     */
316	    private String primaryIdentifier(Owner owner) {
317	        return owner.getMemberId();
318	    }
319	
320	    /**
321	     * Renders a value as a JSON string literal for the structured audit event: {@code null} becomes
322	     * the JSON {@code null} keyword, otherwise the value is quoted with the JSON-significant
323	     * characters ({@code "} and {@code \}) escaped. The derived identifiers this carries never contain
324	     * such characters, but escaping keeps the emitted event valid JSON regardless.
325	     *
326	     * @param value the value to render, or {@code null}
327	     * @return the JSON representation of the value
328	     */
329	    private String jsonString(String value) {
330	        if (value == null) {
331	            return "null";
332	        }
333	        return "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
334	    }
335	
336	    /**
337	     * Assembles an ordered set of already-rendered fields into a compact JSON object literal for a
338	     * structured audit event: each entry becomes {@code "<key>":<value>} in insertion order, the
339	     * entries are joined by commas and wrapped in braces, with no whitespace. Values are inserted
340	     * verbatim, so a numeric field passes its bare digits (for example {@code String.valueOf(seq)})
341	     * and a string field passes its {@link #jsonString(String) quoted} form. This is the single
342	     * definition of how the structured audit events are serialized, so a new field is added by
343	     * putting one more entry on the ordered map rather than by editing a positional format string.
344	     *
345	     * @param fields the event's fields in the order they should appear, each value already rendered as JSON
346	     * @return the compact JSON object literal for the event
347	     */
348	    private String jsonObject(Map<String, String> fields) {
349	        return fields.entrySet().stream()
350	            .map(entry -> "\"" + entry.getKey() + "\":" + entry.getValue())
351	            .collect(Collectors.joining(",", "{", "}"));
352	    }
353	
354	    /**
355	     * Renders a persisted owner as the {@code 201 Created} response of the create endpoint. The owner
356	     * is mapped to an {@link OwnerDto}, its {@code bulkSignupWarning} is derived from the owner's
357	     * stored {@code registrationDate} (mirroring {@link #getOwner(Integer)}), and a {@code Location}
358	     * header pointing at {@code /api/owners/{id}} is attached. Isolating the response assembly here
359	     * keeps {@link #addOwner(OwnerFieldsDto)} a thin orchestration of "create the owner, then render
360	     * it" and gives the created representation one place to grow.
361	     *
362	     * @param owner the persisted owner to render, carrying its generated id and stored fields
363	     * @return the {@code 201 Created} response carrying the owner representation and {@code Location} header
364	     */
365	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
366	        OwnerDto ownerDto = toOwnerDtoWithWarning(owner);
367	        HttpHeaders headers = new HttpHeaders();
368	        headers.setLocation(UriComponentsBuilder.newInstance()
369	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
370	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
371	    }
372	
373	    /**
374	     * Renders a persisted owner as the {@code 200 OK} response shared by the read path
375	     * ({@link #getOwner(Integer)}) and the idempotent-replay path
376	     * ({@link #replayIdempotentCreate(String)}): the owner is stamped with its household member
377	     * count and then mapped to an {@link OwnerDto} carrying its {@code bulkSignupWarning} (see
378	     * {@link #toOwnerDtoWithWarning(Owner)}). Isolating the assembly here keeps both paths rendering
379	     * an existing owner identically rather than each copying the same steps.
380	     *
381	     * @param owner the persisted owner to render
382	     * @return the {@code 200 OK} response carrying the owner representation
383	     */
384	    private ResponseEntity<OwnerDto> okOwnerResponse(Owner owner) {
385	        applyHouseholdMemberCount(owner);
386	        return new ResponseEntity<>(toOwnerDtoWithWarning(owner), HttpStatus.OK);
387	    }
388	
389	    /**
390	     * Maps a persisted owner to the {@link OwnerDto} returned by every rendered response, stamping
391	     * its {@code bulkSignupWarning} from the owner's stored {@code registrationDate} (see
392	     * {@link #bulkSignupWarning(LocalDate)}) and its {@code capacityWarning} from the owner's
393	     * {@code city} (see {@link #capacityWarning(String)}). This is the single definition of how an
394	     * owner becomes its response representation, shared by the read, idempotent-replay and create
395	     * responses, so all three derive the rendered fields identically rather than each copying the
396	     * mapping.
397	     *
398	     * @param owner the persisted owner to map
399	     * @return the owner representation with its {@code bulkSignupWarning} and {@code capacityWarning} set
400	     */
401	    private OwnerDto toOwnerDtoWithWarning(Owner owner) {
402	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
403	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
404	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
405	        ownerDto.setRiskFlag(riskFlag(owner));
406	        return ownerDto;
407	    }
408	
409	    /**
410	     * Reports whether an owner should be flagged for review. The flag is true when any of three
411	     * independent signals hold and false only when none does: the owner is a possible (soft)
412	     * duplicate (its {@code possibleDuplicate} flag is set, see
413	     * {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)}), the owner's email domain is
414	     * disposable-adjacent (see {@link #isDisposableAdjacentEmail(String)}) or the owner's city is
415	     * over its soft capacity (see {@link #capacityWarning(String)}). This is the single definition
416	     * of an owner's risk flag, shared by every rendered response.
417	     *
418	     * @param owner the persisted owner to assess
419	     * @return {@code true} when any risk signal holds, otherwise {@code false}
420	     */
421	    private boolean riskFlag(Owner owner) {
422	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
423	            || isDisposableAdjacentEmail(owner.getEmail())
424	            || capacityWarning(owner.getCity());
425	    }
426	
427	    /**
428	     * Reports whether an email's domain is disposable-adjacent: its domain (see
429	     * {@link #emailDomain(String)}) equals one of the known disposable domains (see
430	     * {@link #DISPOSABLE_EMAIL_DOMAINS}) or is a subdomain of one (it ends with {@code '.'} followed
431	     * by a disposable domain), compared case-insensitively. An exact disposable domain is already
432	     * rejected at intake by {@link #normalizeEmail(String)}, so a persisted owner reaches this rule
433	     * only through a subdomain of a disposable domain. An owner without an email has no domain and
434	     * is never disposable-adjacent.
435	     *
436	     * @param email the owner's stored email, or {@code null} when none was supplied
437	     * @return {@code true} when the email's domain is a disposable domain or a subdomain of one
438	     */
439	    private boolean isDisposableAdjacentEmail(String email) {
440	        String domain = emailDomain(email);
441	        if (domain == null) {
442	            return false;
443	        }
444	        return DISPOSABLE_EMAIL_DOMAINS.stream()
445	            .anyMatch(disposable -> domain.equals(disposable) || domain.endsWith("." + disposable));
446	    }
