544	    /**
545	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
546	     * The address is normalized in place (so a required-field check that follows rejects an
547	     * address blank after normalization), the required fields are checked, the telephone and
548	     * email are normalized in place, and the resulting owner is rejected when its derived
549	     * identity key already belongs to another owner. Each rule
550	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
551	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
552	     * to be mapped and saved.
553	     *
554	     * @param ownerFieldsDto the submitted owner fields, normalized in place
555	     */
556	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
557	        applyAddress(ownerFieldsDto);
558	        validateRequiredFields(ownerFieldsDto);
559	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
560	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
561	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
562	        rejectDuplicateIdentity(ownerFieldsDto);
563	        rejectCityAtCapacity(ownerFieldsDto.getCity());
564	        rejectDailyLimitExceeded(registrationDate);
565	    }
