567	    /**
568	     * Applies an owner's address to the submitted fields, normalizing it in place into the
569	     * canonical form stored and returned for the owner. This is the single intake step that owns
570	     * how a submitted address becomes an owner's stored address: it delegates every transform to
571	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
572	     * the results back onto {@code ownerFieldsDto}.
573	     *
574	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
575	     * is present the two structured lines are normalized in place and the flat {@code address} is
576	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
577	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
578	     * every rule that later reads {@code address} sees the structured value. When no structured
579	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
580	     * backward compatibility.
581	     *
582	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
583	     * blank after normalization in either form is rejected by the required-field check that
584	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
585	     * list of named intake steps and gives address handling one place to grow.
586	     *
587	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
588	     */
589	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
590	        String line1 = ownerFieldsDto.getAddressLine1();
591	        if (line1 != null && !line1.isBlank()) {
592	            String normalizedLine1 = normalizeAddress(line1);
593	            ownerFieldsDto.setAddressLine1(normalizedLine1);
594	            String line2 = ownerFieldsDto.getAddressLine2();
595	            if (line2 != null && !line2.isBlank()) {
596	                String normalizedLine2 = normalizeAddress(line2);
597	                ownerFieldsDto.setAddressLine2(normalizedLine2);
598	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
599	            } else {
600	                ownerFieldsDto.setAddressLine2(null);
601	                ownerFieldsDto.setAddress(normalizedLine1);
602	            }
603	        } else {
604	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
605	        }
606	    }
