608	    /**
609	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
610	     * falls on a business day. The date supplied on the request is used when present, otherwise the
611	     * server's current date is used. When that effective date lands on a Saturday, Sunday or listed
612	     * public holiday it is rolled forward to the next non-holiday business day; a non-holiday weekday
613	     * is left unchanged. This single adjusted date
614	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
615	     * membership number's year segment, the per-day create limit) is computed against.
616	     *
617	     * A supplied registration date later than the server's current date is rejected with an
618	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
619	     *
620	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
621	     * @return the effective registration date rolled forward to the next business day
622	     */
623	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
624	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
625	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
626	            throw new InvalidFieldsException(List.of("registrationDate"));
627	        }
628	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
629	        return toBusinessDay(effective);
630	    }
631	
632	    /**
633	     * The fixed public holidays the business-day roll skips. A date landing on any of these is
634	     * advanced, along with weekends, until it reaches the next non-holiday business day.
635	     */
636	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
637	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
638	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
639	        LocalDate.parse("2026-12-28"));
640	
641	    /**
642	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public holiday is
643	     * advanced one day at a time until it reaches a weekday that is not a public holiday, while a
644	     * date already on such a business day is returned unchanged.
645	     *
646	     * @param date the date to adjust
647	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
648	     */
649	    private LocalDate toBusinessDay(LocalDate date) {
650	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
651	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
652	                || PUBLIC_HOLIDAYS.contains(date)) {
653	            date = date.plusDays(1);
654	        }
655	        return date;
656	    }
