658	    /**
659	     * The maximum number of owners that may be created on a single day. Once this many owners
660	     * already carry today's {@code registrationDate}, no further owner may be created today.
661	     */
662	    private static final long DAILY_OWNER_LIMIT = 100L;
663	
664	    /**
665	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
666	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
667	     * date the new owner would be stored with, so owners are capped per business day. When the limit
668	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
669	     * advice renders as a 429 Too Many Requests response.
670	     *
671	     * @param registrationDate the adjusted business-day registration date of the owner being created
672	     */
673	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
674	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
675	            throw new DailyOwnerLimitExceededException(registrationDate);
676	        }
677	    }
