679	    /**
680	     * Counts the existing owners whose adjusted business-day {@code registrationDate} equals the
681	     * given date. This is the single definition of the per-day owner count, shared by the per-day
682	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
683	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
684	     *
685	     * @param registrationDate the adjusted business-day registration date to count owners against
686	     * @return the number of existing owners carrying that registration date
687	     */
688	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
689	        return this.clinicService.findAllOwners().stream()
690	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
691	            .count();
692	    }
