701	    /**
702	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
703	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
704	     * count is taken against the same adjusted date owners are stored with, mirroring the
705	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
706	     *
707	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
708	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
709	     */
710	    private boolean bulkSignupWarning(LocalDate registrationDate) {
