717	    /**
718	     * The maximum number of owners a single city may hold. Once a city already contains this
719	     * many owners, no further owner may be created in it.
720	     */
721	    private static final long CITY_OWNER_CAPACITY = 50L;
722	
723	    /**
724	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
725	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
726	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
727	     * which the exception advice renders as a 409 Conflict response.
728	     *
729	     * @param city the city of the owner being created
730	     */
731	    private void rejectCityAtCapacity(String city) {
732	        if (countOwnersInCity(city) >= CITY_OWNER_CAPACITY) {
733	            throw new CityCapacityExceededException(city);
734	        }
