737	    /**
738	     * Counts the existing owners whose {@code city} equals the given city, compared
739	     * case-insensitively. This is the single definition of the per-city owner count, shared by the
740	     * hard capacity rejection ({@link #rejectCityAtCapacity(String)}) and the approaching-capacity
741	     * warning ({@link #capacityWarning(String)}), so both measure a city's occupancy identically.
742	     *
743	     * @param city the city to count owners against
744	     * @return the number of existing owners whose city matches
745	     */
746	    private long countOwnersInCity(String city) {
747	        return this.clinicService.findAllOwners().stream()
748	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
749	            .count();
750	    }
