752	    /**
753	     * The number of owners a city must already contain before it is flagged as approaching its
754	     * capacity limit. Once a city holds at least this many owners (but is not yet at
755	     * {@link #CITY_OWNER_CAPACITY}), the create and read responses report {@code capacityWarning}
756	     * true for owners in that city.
757	     */
758	    private static final long CITY_CAPACITY_WARNING_THRESHOLD = 40L;
759	
760	    /**
761	     * Reports whether the given city is approaching its capacity limit, i.e. whether it already
762	     * contains between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and {@link #CITY_OWNER_CAPACITY}
763	     * minus one owners (40 to 49) inclusive. The count is taken the same way the hard rejection
764	     * counts a city's owners ({@link #countOwnersInCity(String)}). A {@code null} city never warns.
765	     *
766	     * @param city the city to test, or {@code null}
767	     * @return {@code true} when the city holds 40 to 49 owners, otherwise {@code false}
768	     */
769	    private boolean capacityWarning(String city) {
770	        if (city == null) {
771	            return false;
772	        }
773	        long count = countOwnersInCity(city);
774	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_OWNER_CAPACITY;
