777	    /**
778	     * Builds the unified {@code memberId} assigned to a newly created owner. The id is formatted as
779	     * {@code '<REGION><FY><HASH8><CHK>'}, concatenating (with no separators) the owner's identity
780	     * region code (see {@link Owner#getIdentityRegionCode()}, rendered {@code 'UNKNOWN'} when the
781	     * owner has no known region), the two-digit fiscal-year segment its business-day-adjusted {@code registrationDate}
782	     * falls in (see {@link Owner#fiscalYearSegment(LocalDate)}), its identity hash (see
783	     * {@link Owner#getIdentityHash()}, the first 8 upper-case hex characters of the SHA-256 digest
784	     * over the owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}) and
785	     * a single Luhn check digit (see {@link Owner#luhnCheckDigit(String)}) computed over the digits of
786	     * {@code <REGION><FY><HASH8>}. The composed base is then de-duplicated against existing owners
787	     * (see {@link #deduplicateMemberId(String)}). The base carries no sequence number, so two owners
788	     * sharing a region, fiscal year, telephone and last name resolve to the same base and are
789	     * separated only by de-duplication.
790	     *
791	     * @param owner the owner being created, whose fields the id is derived from
792	     * @return the formatted member id
793	     */
794	    private String memberIdFor(Owner owner) {
795	        String prefix = owner.getIdentityRegionCode()
796	            + Owner.fiscalYearSegment(owner.getRegistrationDate())
797	            + owner.getIdentityHash();
798	        return deduplicateMemberId(prefix + Owner.luhnCheckDigit(prefix));
799	    }
800	
801	    /**
802	     * Ensures the computed {@code memberId} is unique across existing owners. When the given base id
803	     * collides with an existing owner's {@code memberId}, {@code '-<n>'} is appended with the smallest
804	     * {@code n} of 2 or more that yields an id no existing owner already carries.
805	     *
806	     * @param baseCode the member id computed for the owner being created
807	     * @return the base id when it is already unique, otherwise the de-duplicated id
808	     */
809	    private String deduplicateMemberId(String baseCode) {
810	        Set<String> existing = this.clinicService.findAllOwners().stream()
811	            .map(Owner::getMemberId)
812	            .filter(Objects::nonNull)
813	            .collect(Collectors.toSet());
814	        if (!existing.contains(baseCode)) {
815	            return baseCode;
816	        }
817	        int n = 2;
818	        while (existing.contains(baseCode + "-" + n)) {
819	            n++;
820	        }
821	        return baseCode + "-" + n;
822	    }
