824	    /**
825	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
826	     * with the owner being created, compared case-insensitively. The count is taken before the
827	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
828	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
829	     *
830	     * @param firstName the first name of the owner being created
831	     * @param lastName the last name of the owner being created
832	     * @return the number of pre-existing owners sharing the same first and last name
833	     */
834	    private int countNamesakes(String firstName, String lastName) {
835	        return (int) this.clinicService.findAllOwners().stream()
836	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
837	                && lastName.equalsIgnoreCase(existing.getLastName()))
838	            .count();
839	    }
