841	    /**
842	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
843	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it does not share
844	     * an existing owner's identity key. A member that declared its household via
845	     * {@code sharesHousehold} is a deliberate addition to a known household, not a suspected
846	     * duplicate, so it is never flagged. Otherwise it is a possible duplicate when an existing owner
847	     * shares the Soundex code of its {@code lastName} and its {@code postcode} while carrying a
848	     * different identity key (see {@link #findPossibleDuplicate(Owner)}). When such an owner is
849	     * found, {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to the
850	     * matching owner's id; otherwise {@code possibleDuplicate} is set {@code false} and no matching
851	     * id is recorded. An owner without a postcode can share no postcode and is never a possible
852	     * duplicate.
853	     *
854	     * @param owner the owner being created, already carrying its normalized telephone and postcode
855	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
856	     */
857	    private void applyPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
858	        owner.setPossibleDuplicate(false);
859	        owner.setPossibleDuplicateOf(null);
860	        if (sharesHousehold(ownerFieldsDto)) {
861	            return;
862	        }
863	        findPossibleDuplicate(owner).ifPresent(existing -> {
864	            owner.setPossibleDuplicate(true);
865	            owner.setPossibleDuplicateOf(existing.getId());
866	        });
867	    }
868	
869	    /**
870	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
871	     * duplicate: a non-deleted owner whose {@code lastName} shares the new owner's Soundex code (see
872	     * {@link Owner#soundex(String)}) and whose {@code postcode} matches, while carrying a different
873	     * identity key (see {@link Owner#identityKey(String, String, String)}). Requiring a differing
874	     * identity key keeps a hard duplicate — already rejected with 409 by
875	     * {@link #rejectDuplicateIdentity(OwnerFieldsDto)} — from also being flagged as a soft match, so
876	     * the two household members whose telephones differ (hence differing identity keys, but matching
877	     * Soundex and postcode) are exactly the soft matches surfaced here. This is the single definition
878	     * of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records
879	     * the outcome on the owner. An owner without a postcode can share no postcode and matches nothing,
880	     * so {@link java.util.Optional#empty()} is returned.
881	     *
882	     * @param owner the owner being created, already carrying its normalized telephone and postcode
883	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
884	     */
885	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
886	        if (owner.getPostcode() == null) {
887	            return java.util.Optional.empty();
888	        }
889	        String soundex = Owner.soundex(owner.getLastName());
890	        String identityKey = owner.getIdentityKey();
891	        return this.clinicService.findAllOwners().stream()
892	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
893	            .filter(existing -> !identityKey.equals(existing.getIdentityKey())
894	                && soundex.equals(Owner.soundex(existing.getLastName()))
895	                && owner.getPostcode().equals(existing.getPostcode()))
896	            .findFirst();
897	    }
