900	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
901	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
902	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
903	     * the names of every offending field, which the exception advice renders as a 400 response
904	     * with an {@code errors} array.
905	     *
906	     * @param ownerFieldsDto the submitted owner fields
907	     */
908	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
909	        List<String> missing = new ArrayList<>();
910	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
911	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
912	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
913	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
914	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
915	        if (!missing.isEmpty()) {
916	            throw new RequiredFieldsMissingException(missing);
917	        }
918	    }
