926	    /**
927	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
928	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
929	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
930	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
931	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
932	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
933	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
934	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
935	     *
936	     * @param telephone the submitted telephone value
937	     * @return the normalized E.164 telephone
938	     */
939	    private String normalizeTelephone(String telephone) {
940	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
941	        String e164;
942	        if (cleaned.startsWith("+")) {
943	            e164 = "+" + cleaned.substring(1);
944	        } else {
945	            String national = cleaned;
946	            if (national.startsWith("0")) {
947	                national = national.substring(1);
948	            }
949	            e164 = "+61" + national;
950	        }
951	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
952	            throw new InvalidFieldsException(List.of("telephone"));
953	        }
954	        validateNationalNumberLength(e164);
955	        return e164;
956	    }
957	
958	    /**
959	     * Validates the national-number length of an already syntactically valid E.164 telephone
960	     * against its country code. When the number carries a country code this application recognizes
961	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
962	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
963	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
964	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
965	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
966	     * that is not recognized carries no per-country length rule and is left to the general
967	     * 8-to-15-digit E.164 check.
968	     *
969	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
970	     */
971	    private void validateNationalNumberLength(String e164) {
972	        String countryCode = Owner.countryCodeOf(e164);
973	        if (countryCode == null) {
974	            return;
975	        }
976	        int nationalLength = e164.length() - 1 - countryCode.length();
977	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
978	            throw new InvalidFieldsException(List.of("telephone"));
979	        }
980	    }
981	
982	    /**
983	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
984	     * and a domain containing at least one dot, none of the parts holding whitespace or a
985	     * second {@code @}.
986	     */
987	    private static final java.util.regex.Pattern EMAIL_PATTERN =
988	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
989	
990	    /**
991	     * Disposable email domains an owner may not register with. An email whose domain (compared
992	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
993	     */
994	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
995	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
996	
997	    /**
998	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
999	     * accepted and returned unchanged. When present it must be a syntactically valid address
1000	     * whose domain is not on the disposable-domain blocklist (see
1001	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
1002	     * present but syntactically invalid or on a disposable domain an
1003	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
1004	     * response naming the {@code email} field.
1005	     *
1006	     * @param email the submitted email value, or {@code null} when omitted
1007	     * @return the lower-cased email, or {@code null} when none was supplied
1008	     */
1009	    private String normalizeEmail(String email) {
1010	        if (email == null) {
1011	            return null;
1012	        }
1013	        String trimmed = email.trim();
1014	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
1015	            throw new InvalidFieldsException(List.of("email"));
1016	        }
1017	        String domain = emailDomain(trimmed);
1018	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
1019	            throw new InvalidFieldsException(List.of("email"));
1020	        }
1021	        return canonicalEmail(trimmed);
1022	    }
1023	
1024	    /**
1025	     * Reduces an email to the canonical form used both to store it and to compare it against
1026	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
1027	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
1028	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
1029	     * value read back off an existing owner without risk of rejecting it. This is the single
1030	     * definition of email identity: two emails denote the same address exactly when they
1031	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
1032	     * an email already on an existing owner can be compared for equality after both pass through
1033	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
1034	     *
1035	     * @param email the email to canonicalize, or {@code null} when none was supplied
1036	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
1037	     */
1038	    private String canonicalEmail(String email) {
1039	        if (email == null) {
1040	            return null;
1041	        }
1042	        return email.trim().toLowerCase(java.util.Locale.ROOT);
1043	    }
1044	
1045	    /**
1046	     * Extracts the lower-cased domain of an email — everything after its final {@code '@'}. This is
1047	     * the single definition of an email's domain, shared wherever an owner's email is matched by its
1048	     * domain (for example the disposable-domain blocklist applied in {@link #normalizeEmail(String)}),
1049	     * so every such rule reads the domain identically rather than re-deriving it. A {@code null} email
1050	     * (none was supplied) has no domain and yields {@code null}. Like {@link #canonicalEmail(String)}
1051	     * no validation is performed, so this can be applied to a value read back off an existing owner as
1052	     * readily as to one being normalized; a caller that needs a syntactically valid address validates
1053	     * it first. The domain is lower-cased so it compares case-insensitively, matching how
1054	     * {@link #DISPOSABLE_EMAIL_DOMAINS} is compared. For example {@code "jane@Example.COM"} yields
1055	     * {@code "example.com"}.
1056	     *
1057	     * @param email the email whose domain to extract, or {@code null} when none was supplied
1058	     * @return the lower-cased domain, or {@code null} when {@code email} is {@code null}
1059	     */
1060	    private String emailDomain(String email) {
1061	        if (email == null) {
1062	            return null;
1063	        }
1064	        return email.substring(email.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
1065	    }
1066	
1067	    /**
1068	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
1069	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
1070	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
1071	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
1072	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
1073	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
1074	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
1075	     * 400 response naming the {@code postcode} field.
1076	     *
1077	     * @param postcode the submitted postcode, or {@code null} when omitted
1078	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
1079	     */
1080	    private void validatePostcode(String postcode, String city) {
1081	        if (postcode == null) {
1082	            return;
1083	        }
1084	        if (!postcode.matches("^[0-9]{4}$")) {
1085	            throw new InvalidFieldsException(List.of("postcode"));
1086	        }
1087	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
1088	        if (range != null) {
1089	            int value = Integer.parseInt(postcode);
1090	            if (value < range[0] || value > range[1]) {
1091	                throw new InvalidFieldsException(List.of("postcode"));
1092	            }
1093	        }
1094	    }
1095	
1096	    /**
1097	     * Rejects a new owner that is an exact identity duplicate of an existing owner. An owner's
1098	     * identity is its single derived identity key (see
1099	     * {@link Owner#identityKey(String, String, String)}) — the SHA-256 hex digest over its
1100	     * normalized {@code telephone}, canonical {@code email} and the Soundex code of its
1101	     * {@code lastName} — so a new owner is a hard duplicate only when some existing, non-deleted
1102	     * owner carries the same identity key. The email-domain blocklist has already been applied when
1103	     * the email was normalized ahead of this check, so a disposable-domain email is rejected before
1104	     * duplicate detection runs. Two owners that merely belong to the same household (the same last
1105	     * name and postcode) but carry different telephones now have distinct identity keys and are not

